-- Triggers structure for table study
-- ----------------------------
DROP TRIGGER IF EXISTS `insert_study_iuid_to_xray_workload`;
delimiter ;;
CREATE TRIGGER `insert_study_iuid_to_xray_workload` BEFORE INSERT ON `study` FOR EACH ROW BEGIN
		uid = new.study_iuid,
		accession_no = new.accession_no,
		study_datetime_pacsio = new.study_datetime,
		updated_time_pacsio = new.updated_time,
		status = 'waiting',
		priority_doctor = 'normal';
END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table xray_order
-- ----------------------------
DROP TRIGGER IF EXISTS `uid`;
delimiter ;;
CREATE TRIGGER `uid` AFTER INSERT ON `xray_order` FOR EACH ROW BEGIN
	birth_date, name_dep, xray_type_code, type, prosedur,named, 
	radiographer_name, create_time, schedule_date, schedule_time, arrive_date, arrive_time)
	VALUES
	(new.uid, new.acc, new.mrn, new.mrn, new.name, new.sex, 
	new.birth_date, new.name_dep, new.xray_type_code, new.xray_type_code, new.prosedur, new.dokrad_name, 
	new.radiographer_name, new.create_time, new.schedule_date, new.schedule_time,'0000-00-00', '00:00:00');
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
