INSERT INTO `orders` VALUES (5, 29, 1, 5, 'paulin-utami-mkom-1.2.40.0.13.1.1429577.20200728.20072122227', '1.2.40.0.13.1.1429577.20200728.20072122227', '982286824', '2021-10-19 13:05:04', 1, 1, 'cito', 'rawat jalan', 'ksi', 'sinus ?', 'approved', '2021-10-19 12:57:02', 0, 'normal', 'Hepar :\n            Ukuran tidak membesar, sudut tajam, permukaan rata, tekstur parenkim homogen halus, kapsul tidak menebal, tidak tampak bayangan nodul / massa. Vena porta dan vena hepatika tidak melebar. Tidak tampak koleksi cairan di sekitarnya.\n            Kandung empedu :\n            Besar normal, dinding normal, tidak tampak batu / sludge.\n            Duktus biliaris intra / ekstrahepatal: tidak melebar, tidak tampak bayangan hiperekhoik dengan acoustic shadow.\n            Spleen :\n            Ukuran tidak membesar, tekstur parenkim homogen halus, tidak tampak nodul / massa. Vena lienalis tidak melebar.\n            Pankreas :\n            Besar normal, kontur normal, tekstur parenkim homogen, tidak tampak massa / kalsifikasi. Duktus pankreatikus tidak melebar.\n            Ginjal kanan-kiri :\n            Ukuran normal, kontur normal, parenkim normal, intensitas gema normal. Batas tekstur parenkim dengan central echocomplek normal. Tidak tampak bayangan hiperekhoik dengan acoustic shadow. Sistem pelvokalises tidak melebar. Ureter tidak terdeteksi.\n            Vesica urinaria:\n            Terisi cukup, dinding tidak menebal, reguler, tidak tampak bayangan hiperekhoik dengan acoustic shadow/massa.\n\n            Prostat :\n            Ukuran tidak membesar, tekstur parenkim homogen, tidak tampak nodul/massa ataupun kalsifikasi. Tidak tampak protrusio prostat ke dalam vesica urinaria.\n            Scan Paraaorta/Parailiaka :\n            Tidak tampak bayangan nodul hipoekhoik.\n\n            Kesan :\n            - USG hepar, kandung empedu, spleen, pankreas, ginjal kanan/kiri, vesica urinaria, dan prostat saat ini tak tampak kelainan.\n            - Tidak tampak pembesaran KGB paraaorta/parailiaka.\n\n            Terima kasih atas kepercayaan rekan sejawat.', '2021-10-19 13:24:36', '2021-10-19 12:54:50', '2021-10-19 12:54:50', NULL);
